mapper.select:
SELECT user_id AS userId, topic_id AS topicId
FROM defense_records
WHERE defense_id = #{defenseId}

select topic_id as topicId, teacher_id as teacherId, topic_name as topicName, topic_description as topicDescription, defense_time as defenseTime, created_at as createdAt from defense_topics
topic_name like concat('%', #{keyword}, '%')
order by defense_time DESC limit #{offset}, #{limit}

select count(dr.defense_id)
from defense_records dr
where dr.user_id = #{userId}
  and dr.topic_id = #{topicId}

select user_id as userId
from users
where user_number = #{userNumber}

SELECT video_url FROM defense_records
WHERE user_id = #{userId} AND topic_id = #{topicId}
    LIMIT 1

select video_ppt_words, video_words
from defense_records
where topic_id = #{topicId}

